# 分布检验：从上游概率分布插件读取分布接口，执行拟合优度检验
# 分布接口支持：scipy 冻结分布对象；或包含 name/type/scipy_name/args/kwargs/estimated_param_count 的字典
import io
import csv as _csv
import numpy as np
import pandas as pd
from scipy import stats

method = {{method}}
value_column = {{value_column}}
alpha = float({{alpha}})
min_expected = float({{min_expected}})


def _to_frame(value):
    if isinstance(value, pd.DataFrame):
        return value.copy()
    if isinstance(value, bytes):
        for encoding in ('utf-8-sig', 'utf-8', 'gbk', 'gb18030'):
            try:
                return pd.read_csv(io.StringIO(value.decode(encoding)))
            except UnicodeDecodeError:
                continue
        raise RuntimeError('CSV 编码无法识别')
    if isinstance(value, str):
        return pd.read_csv(io.StringIO(value.lstrip('\ufeff')))
    raise RuntimeError('输入 data 必须是 CSV 文本或 DataFrame')


def _fmt(value, digits=6):
    try:
        number = float(value)
        return None if not np.isfinite(number) else round(number, digits)
    except (TypeError, ValueError):
        return value


def _distribution_interface(value):
    if value is None:
        raise RuntimeError('请连接并先运行上游的概率分布插件')
    if hasattr(value, 'cdf'):
        dist = value
        dist_name = getattr(getattr(value, 'dist', None), 'name', value.__class__.__name__)
        dist_type = '离散型' if hasattr(value, 'pmf') else '连续型'
        args = list(getattr(value, 'args', ()) or ())
        kwargs = dict(getattr(value, 'kwds', {}) or {})
        return dist, str(dist_name), dist_type, args, kwargs, len(args) + len(kwargs)
    if not isinstance(value, dict):
        raise RuntimeError('distribution 必须是概率分布插件输出的分布接口（字典或 scipy 冻结分布对象）')
    scipy_name = value.get('scipy_name') or value.get('scipy分布名')
    if not scipy_name or not hasattr(stats, str(scipy_name)):
        raise RuntimeError('分布接口缺少有效的 scipy_name，无法取得 CDF/PMF')
    factory = getattr(stats, str(scipy_name))
    args = list(value.get('args', value.get('位置参数', [])) or [])
    kwargs = dict(value.get('kwargs', value.get('命名参数', {})) or {})
    try:
        dist = factory(*args, **kwargs)
    except Exception as exc:
        raise RuntimeError('概率分布插件返回的参数无法构造理论分布：' + str(exc))
    kind = value.get('type') or value.get('分布类型')
    if kind in ('discrete', '离散', '离散型'):
        dist_type = '离散型'
    elif kind in ('continuous', '连续', '连续型'):
        dist_type = '连续型'
    else:
        dist_type = '离散型' if hasattr(dist, 'pmf') else '连续型'
    display_name = value.get('name') or value.get('分布名称') or str(scipy_name)
    param_count = int(value.get('estimated_param_count', value.get('估计参数个数', len(args) + len(kwargs))))
    return dist, str(display_name), dist_type, args, kwargs, max(0, param_count)


if data is None:
    raise RuntimeError('请连接并先运行上游的数据导入插件')
if not 0 < alpha < 1:
    raise RuntimeError('显著性水平必须在 0 到 1 之间')
if min_expected < 1:
    raise RuntimeError('最小理论期望频数不能小于 1')

df = _to_frame(data)
if not value_column:
    candidates = [str(c) for c in df.columns if pd.to_numeric(df[c], errors='coerce').notna().sum() >= max(3, int(len(df) * 0.8))]
    if not candidates:
        raise RuntimeError('没有找到可检验的数值列，请先检查数据内容')
    value_column = candidates[0]
if value_column not in df.columns:
    raise RuntimeError('数据中找不到数值列「' + str(value_column) + '」')
sample = pd.to_numeric(df[value_column], errors='coerce').dropna().to_numpy(dtype=float)
if len(sample) < 5:
    raise RuntimeError('有效数值样本不足 5 个，无法进行分布检验')

dist, dist_name, dist_type, dist_args, dist_kwargs, estimated_param_count = _distribution_interface(distribution)
chosen_method = method
if method == '自动选择':
    chosen_method = '卡方拟合优度检验' if dist_type == '离散型' else 'Kolmogorov-Smirnov检验'
if chosen_method == 'Kolmogorov-Smirnov检验' and dist_type != '连续型':
    raise RuntimeError('Kolmogorov-Smirnov检验仅用于连续型分布；当前理论分布为离散型，请改用卡方拟合优度检验')
if chosen_method == '卡方拟合优度检验' and dist_type != '离散型':
    raise RuntimeError('卡方拟合优度检验在本插件中用于离散型分布；当前理论分布为连续型，请改用 Kolmogorov-Smirnov检验')

parameter_text = '位置参数=' + str(dist_args) + '；命名参数=' + str(dist_kwargs)
report = {
    '报告名称': '分布检验报告',
    '数据列': str(value_column),
    '有效样本量': int(len(sample)),
    '理论分布': dist_name,
    '分布类型': dist_type,
    '估计参数': parameter_text,
    '检验方法': chosen_method,
    '显著性水平α': alpha,
}

if chosen_method == 'Kolmogorov-Smirnov检验':
    result = stats.kstest(sample, dist.cdf)
    statistic = float(result.statistic)
    p_value = float(result.pvalue)
    report.update({
        'KS统计量D': _fmt(statistic),
        'p值': _fmt(p_value),
        '参数估计说明': '分布参数由上游概率分布插件提供；若参数由同一样本估计，常规KS的p值为近似结果',
    })
else:
    rounded = np.rint(sample).astype(int)
    if not np.allclose(sample, rounded, atol=1e-9):
        raise RuntimeError('卡方拟合优度检验要求离散整数样本；所选列包含非整数值')
    low, high = int(rounded.min()), int(rounded.max())
    values = np.arange(low, high + 1)
    observed = np.array([(rounded == value).sum() for value in values], dtype=float)
    probabilities = np.asarray(dist.pmf(values), dtype=float)
    if len(probabilities) != len(values) or np.any(~np.isfinite(probabilities)) or np.any(probabilities < 0):
        raise RuntimeError('概率分布插件返回的 PMF 无效')
    probabilities[0] += max(0.0, float(dist.cdf(low - 1)))
    probabilities[-1] += max(0.0, 1.0 - float(dist.cdf(high)))
    expected = probabilities * len(rounded)
    groups = [[str(value), float(obs), float(exp)] for value, obs, exp in zip(values, observed, expected)]
    while len(groups) > 2 and min(group[2] for group in groups) < min_expected:
        index = min(range(len(groups)), key=lambda i: groups[i][2])
        neighbor = 1 if index == 0 else len(groups) - 2 if index == len(groups) - 1 else (index - 1 if groups[index - 1][2] <= groups[index + 1][2] else index + 1)
        a, b = sorted((index, neighbor))
        groups[a] = [groups[a][0] + '～' + groups[b][0], groups[a][1] + groups[b][1], groups[a][2] + groups[b][2]]
        groups.pop(b)
    if len(groups) < 2 or any(group[2] < min_expected for group in groups):
        raise RuntimeError('合并低频组后仍无法满足理论期望频数要求，请增加样本量或调整上游理论分布')
    obs = np.array([group[1] for group in groups], dtype=float)
    exp = np.array([group[2] for group in groups], dtype=float)
    exp *= obs.sum() / exp.sum()
    statistic = float(np.sum((obs - exp) ** 2 / exp))
    dof = int(len(groups) - 1 - estimated_param_count)
    if dof < 1:
        raise RuntimeError('合并后有效分组过少，扣除上游估计参数后自由度不足 1')
    p_value = float(stats.chi2.sf(statistic, dof))
    report.update({
        '卡方统计量χ²': _fmt(statistic),
        '自由度': dof,
        'p值': _fmt(p_value),
        '合并后组数': int(len(groups)),
        '最小理论期望频数': _fmt(min(group[2] for group in groups)),
        '分组明细': [{'取值范围': group[0], '实际频数': int(group[1]), '理论期望频数': _fmt(group[2], 4)} for group in groups],
    })

if p_value < alpha:
    decision = '拒绝原假设'
    final_conclusion = '在显著性水平 α=' + str(alpha) + ' 下，样本与“' + dist_name + '”存在显著差异，不能认为样本服从该理论分布。'
else:
    decision = '不能拒绝原假设'
    final_conclusion = '在显著性水平 α=' + str(alpha) + ' 下，未发现样本与“' + dist_name + '”存在显著差异，样本可以认为服从该理论分布。'
report['假设检验决策'] = decision
report['最终结论'] = final_conclusion

rows = []
def _flatten(value, prefix=''):
    if isinstance(value, dict):
        for key, item in value.items():
            _flatten(item, prefix + ('｜' if prefix else '') + str(key))
    elif isinstance(value, list):
        for index, item in enumerate(value, 1):
            _flatten(item, prefix + '｜第' + str(index) + '项')
    else:
        rows.append((prefix, '' if value is None else str(value)))
_flatten(report)
buf = io.StringIO()
writer = _csv.writer(buf, lineterminator='\n')
writer.writerow(['指标', '值'])
writer.writerows(rows)
report_csv = buf.getvalue()

print('【分布检验报告】' + str(value_column) + ' → ' + dist_name)
print('检验方法：' + chosen_method + '；样本量 n=' + str(len(sample)) + '；α=' + str(alpha))
print('统计量=' + ('%.6g' % statistic) + '；p值=' + ('%.6g' % p_value))
print('结论：' + final_conclusion)

if isinstance(data, str):
    out_data = data
elif isinstance(data, bytes):
    out_data = data.decode('utf-8-sig')
else:
    out_data = data.to_csv(index=False)
return {'report': report, 'report_csv': report_csv, 'data': out_data}
